const inputData = $('Execute Workflow Trigger').first().json;
const cb = inputData.callback_data || '';
let cart = [];
try { cart = JSON.parse(inputData.carrito_json || '[]'); } catch(e) {}

if (cart.length === 0) {
  return [{
    json: {
      mensaje: '\u{1F6D2} Tu carrito est\u00e1 vac\u00edo.',
      reply_markup: { inline_keyboard: [[{ text: '\u{1F6D2} Ver Men\u00fa', callback_data: 'cat_ver_todas' }]] },
      session_updates: { estado_fsm: 'MENU_PRINCIPAL', carrito_json: '[]', contexto_json: '{}' }
    }
  }];
}

let cartText = '\u{1F6D2} *Tu Carrito*\\n\\n';
let total = 0;
cart.forEach((item, i) => {
  const lineTotal = item.qty * item.precio;
  total += lineTotal;
  cartText += (i + 1) + '. ' + item.nombre + ' x' + item.qty + ' \u2014 $' + lineTotal.toFixed(2) + '\\n';
});
cartText += '\\n\u{1F4B0} *Total: $' + total.toFixed(2) + '*';

return [{
  json: {
    mensaje: cartText,
    reply_markup: { inline_keyboard: [
      [{ text: '\u2795 Agregar m\u00e1s', callback_data: 'cat_ver_todas' }],
      [{ text: '\u2705 Confirmar Pedido', callback_data: 'confirm_yes' }]
    ]},
    session_updates: { estado_fsm: 'CARRITO', carrito_json: JSON.stringify(cart), contexto_json: '{}' }
  }
}];
